	/** 
	 * jumpstart the process by instantiating2 Component_
	 */
	protected void jumpStart() throws Throwable {
		LOGGER.info( "\n======== create instances to get the ball rolling  ======== ");

		component_Id = Component_Service.getComponent_Instance()
		.createComponent_( generateNewCommand() )
		.get();

		// ---------------------------------------------
		// set up query subscriptions after the 1st create
		// ---------------------------------------------
		testingStep = "create";
		setUpQuerySubscriptions();

		Component_Service.getComponent_Instance()
				.createComponent_( generateNewCommand() )
				.get();

	}

	/** 
	 * Set up query subscriptions
	 */
	protected void setUpQuerySubscriptions() throws Throwable {
		LOGGER.info( "\n======== Setting Up Query Subscriptions ======== ");
			
		try {            
			subscriber.component_Subscribe().updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetAll update received for Component_ : " + successValue.getComponent_Id());
							  if (successValue.getComponent_Id().equals(component_Id)) {
								  if (testingStep.equals("create")) {
									  testingStep = "update";
									  update();
								  } else if (testingStep.equals("delete")) {
									  testingStep = "complete";
									  state( getAll().size() == sizeOfComponent_List - 1 , "value not deleted from list");
									  LOGGER.info("**********************************************************");
									  LOGGER.info("Component_ test completed successfully...");
									  LOGGER.info("**********************************************************\n");
								  }
							  }
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on component_ consumed")
					);
			subscriber.component_Subscribe( component_Id ).updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetOne update received for Component_ : " + successValue.getComponent_Id() + " in step " + testingStep);
							  testingStep = "delete";
							  sizeOfComponent_List = getAll().size();
							  delete();
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on component_ for component_Id consumed")

					);
			

			}
			catch (Exception e) {
				LOGGER.warning( e.getMessage() );
				throw e;
			}
		}
		
		/** 
	 * read a Component_. 
	 */
	protected Component_ read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created Component_" );

		Component_ entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read Component_ with primary key" );
		msg.append( component_Id );
		
		Component_FetchOneSummary fetchOneSummary = new Component_FetchOneSummary( component_Id );

		try {
			entity = Component_Service.getComponent_Instance().getComponent_( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found Component_ " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a Component_.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a Component_." );

		StringBuilder msg = new StringBuilder( "Failed to update a Component_ : " );        
		Component_ entity = read();
		UpdateComponent_Command command = generateUpdateCommand();
		command.setComponent_Id(entity.getComponent_Id());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created Component_." );

			// for use later on...
			component_Id = entity.getComponent_Id();

			Component_Service proxy = Component_Service.getComponent_Instance();  

			proxy.updateComponent_( command ).get();

			LOGGER.info( "-- Successfully saved Component_ - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + component_Id + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a Component_.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created Component_." );

		Component_ entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read Component_ with id " + component_Id );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read Component_ with id " + component_Id );

			throw e;
		}

		try{
			Component_Service.getComponent_Instance().delete( new DeleteComponent_Command( entity.getComponent_Id() ) ).get();
			LOGGER.info( "-- Successfully deleted Component_ with id " + component_Id );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete Component_ with id " + component_Id );

			throw e;
		}
	}

	/**
	 * get all Component_s.
	 */
	protected List<Component_> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of Component_s:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all Component_ : " );        
		List<Component_> collection  = new ArrayList<>();

		try {
			// call the static get method on the Component_Service
			collection = Component_Service.getComponent_Instance().getAllComponent_();
			assertNotNull( collection, "An Empty collection of Component_ was incorrectly returned.");
			
			// Now print out the values
			Component_ entity = null;            
			Iterator<Component_> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getComponent_Id(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

